# Compact, TUI-like startup disclosure. Collapsed ready state is a true one-line row.
write(
    "packages/web/src/components/PiStartupDisclosure.tsx",
    """import { useEffect, useMemo, useRef, useState } from 'react'\nimport type { PiLiveInitializationStageDto, PiLiveStateDto } from '@agent-lens/protocol'\n\nconst STAGES: Array<{ stage: PiLiveInitializationStageDto; label: string; detail: string }> = [\n  { stage: 'starting_worker', label: '启动 Runtime Worker', detail: '创建独立 Pi 运行进程' },\n  { stage: 'loading_sdk', label: '加载 Pi SDK', detail: '定位并加载当前安装的官方 SDK' },\n  { stage: 'loading_resources', label: '加载资源', detail: '读取配置、扩展与上下文' },\n  { stage: 'creating_session', label: '创建 Pi Session', detail: '建立 Agent Session 与运行时服务' },\n  { stage: 'binding_extensions', label: '绑定扩展界面', detail: '连接 Extension UI 与交互通道' },\n]\n\nfunction formatDuration(value: number | undefined): string {\n  if (value === undefined || !Number.isFinite(value)) return '—'\n  const ms = Math.max(0, value)\n  if (ms < 1) return '<1ms'\n  if (ms < 1_000) return `${Math.round(ms)}ms`\n  return `${(ms / 1_000).toFixed(ms < 10_000 ? 1 : 0)}s`\n}\n\nfunction runtimeModeLabel(state: PiLiveStateDto): string {\n  if (state.runtimeMode === 'session_runtime') return 'Session Runtime'\n  if (state.runtimeMode === 'compatibility') return '兼容模式'\n  return ''\n}\n\nexport function PiStartupDisclosure({\n  state,\n  busy,\n  fallbackError,\n  onRetry,\n  onTerminate,\n}: {\n  state: PiLiveStateDto\n  busy: boolean\n  fallbackError?: string\n  onRetry(): void\n  onTerminate(): void\n}) {\n  const [expanded, setExpanded] = useState(state.status !== 'ready')\n  const [clock, setClock] = useState(() => Date.now())\n  const baseline = useRef({\n    stage: state.initializationStage,\n    elapsed: state.initializationElapsedMs ?? 0,\n    at: Date.now(),\n  })\n\n  useEffect(() => {\n    baseline.current = {\n      stage: state.initializationStage,\n      elapsed: state.initializationElapsedMs ?? baseline.current.elapsed,\n      at: Date.now(),\n    }\n    setClock(Date.now())\n  }, [state.initializationElapsedMs, state.initializationStage, state.runtimeSessionId])\n\n  useEffect(() => {\n    if (state.status === 'ready') setExpanded(false)\n    else if (state.status === 'failed') setExpanded(true)\n  }, [state.status])\n\n  useEffect(() => {\n    if (state.status !== 'initializing') return\n    const timer = window.setInterval(() => setClock(Date.now()), 250)\n    return () => window.clearInterval(timer)\n  }, [state.status])\n\n  const timings = useMemo(() => new Map((state.initializationTimings ?? []).map(item => [item.stage, item.durationMs])), [state.initializationTimings])\n  const completedDuration = useMemo(() => [...timings.values()].reduce((sum, value) => sum + Math.max(0, value), 0), [timings])\n  const elapsed = state.status === 'initializing'\n    ? Math.max(state.initializationElapsedMs ?? 0, baseline.current.elapsed + Math.max(0, clock - baseline.current.at))\n    : state.initializationElapsedMs ?? completedDuration\n  const currentDuration = Math.max(0, elapsed - completedDuration)\n  const title = state.status === 'failed' ? 'Pi 启动失败' : state.status === 'ready' ? 'Pi 已就绪' : '正在准备 Pi'\n  const currentStage = state.initializationStage\n  const sdkVersion = state.sdkVersion || state.capabilities?.sdkVersion\n  const mode = runtimeModeLabel(state)\n  const resources = state.startupResources\n  const resourceGroups = [\n    { label: 'Context', values: resources?.contexts ?? [] },\n    { label: 'Skills', values: resources?.skills ?? [] },\n    { label: 'Prompts', values: resources?.prompts ?? [] },\n    { label: 'Extensions', values: resources?.extensions ?? [] },\n    { label: 'Themes', values: resources?.themes ?? [] },\n  ].filter(group => group.values.length)\n  const startupOutput = state.startupOutput ?? []\n\n  return <details\n    className={`pi-startup-disclosure is-${state.status}`}\n    open={expanded}\n    onToggle={event => setExpanded(event.currentTarget.open)}\n  >\n    <summary>\n      <span className=\"pi-startup-summary-state\" aria-hidden=\"true\"/>\n      <span className=\"pi-startup-summary-copy\"><b>{title}</b>{state.status !== 'ready' && <small>{state.initializationMessage || '准备 Pi Runtime'}</small>}</span>\n      <span className=\"pi-startup-summary-time\">{formatDuration(elapsed)}</span>\n      <span className=\"pi-startup-chevron\" aria-hidden=\"true\">⌄</span>\n    </summary>\n    <div className=\"pi-startup-body\">\n      <div className=\"pi-startup-steps\" aria-label=\"Pi Runtime 启动步骤\">\n        {STAGES.map(item => {\n          const recorded = timings.get(item.stage)\n          const failed = state.status === 'failed' && currentStage === item.stage\n          const active = state.status === 'initializing' && currentStage === item.stage\n          const done = recorded !== undefined || state.status === 'ready'\n          const status = failed ? 'failed' : active ? 'active' : done ? 'done' : 'pending'\n          const duration = recorded ?? ((active || failed) ? currentDuration : undefined)\n          return <div key={item.stage} className={`pi-startup-step is-${status}`}>\n            <span className=\"pi-startup-step-dot\" aria-hidden=\"true\">{done ? '✓' : failed ? '!' : ''}</span>\n            <span className=\"pi-startup-step-copy\"><b>{item.label}</b><small>{item.detail}</small></span>\n            <span className=\"pi-startup-step-time\">{status === 'pending' ? '等待' : active ? `${formatDuration(duration)}+` : formatDuration(duration)}</span>\n          </div>\n        })}\n      </div>\n      {(sdkVersion || mode || state.processId) && <div className=\"pi-startup-meta\">\n        {sdkVersion && <span>Pi v{sdkVersion}</span>}\n        {mode && <span>{mode}</span>}\n        {state.processId && <span>Worker PID {state.processId}</span>}\n      </div>}\n      {resourceGroups.length > 0 && <div className=\"pi-startup-resources\" aria-label=\"Pi 已加载资源\">\n        {resourceGroups.map(group => <div className=\"pi-startup-resource-row\" key={group.label}>\n          <b>[{group.label}]</b><span>{group.values.join(', ')}</span>\n        </div>)}\n      </div>}\n      {startupOutput.length > 0 && <div className=\"pi-startup-output\">\n        <b>[启动输出]</b><pre>{startupOutput.join('\\n')}</pre>\n      </div>}\n      {(resources?.diagnostics.length ?? 0) > 0 && <div className=\"pi-startup-diagnostics\">\n        <b>[资源诊断]</b>{resources!.diagnostics.map((message, index) => <span key={`${index}-${message}`}>{message}</span>)}\n      </div>}\n      {state.status === 'failed' && <div className=\"pi-startup-failure\" role=\"alert\">\n        <b>卡在：{STAGES.find(item => item.stage === currentStage)?.label || state.initializationMessage || '初始化'}</b>\n        <span>{state.error || fallbackError || 'Pi Runtime 未能完成初始化。'}</span>\n      </div>}\n      <div className=\"pi-startup-actions\">\n        {state.status === 'initializing' && <button onClick={event => { event.preventDefault(); onTerminate() }} disabled={busy}>取消启动</button>}\n        {state.status === 'failed' && <><button className=\"primary\" onClick={event => { event.preventDefault(); onRetry() }} disabled={busy}>重试</button><button onClick={event => { event.preventDefault(); onTerminate() }} disabled={busy}>结束 Runtime</button></>}\n      </div>\n    </div>\n  </details>\n}\n""",
)

write(
    "packages/web/src/components/pi-startup-disclosure.css",
    """@reference \"../styles.css\";\n\n.pi-startup-disclosure {\n  margin: 6px 0 10px;\n  overflow: hidden;\n  border: 1px solid var(--al-line);\n  border-radius: 12px;\n  background: color-mix(in srgb, var(--al-soft-2) 56%, var(--al-surface));\n}\n.pi-startup-disclosure > summary {\n  display: grid;\n  min-height: 38px;\n  grid-template-columns: 9px minmax(0, 1fr) auto 16px;\n  align-items: center;\n  gap: 8px;\n  padding: 5px 10px;\n  cursor: pointer;\n  list-style: none;\n  user-select: none;\n}\n.pi-startup-disclosure.is-ready:not([open]) { margin: 4px 0 8px; }\n.pi-startup-disclosure.is-ready:not([open]) > summary { min-height: 34px; padding-block: 3px; }\n.pi-startup-disclosure > summary::-webkit-details-marker { display: none; }\n.pi-startup-summary-state {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--al-muted-2);\n}\n.pi-startup-disclosure.is-initializing .pi-startup-summary-state { background: var(--al-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--al-accent) 12%, transparent); }\n.pi-startup-disclosure.is-ready .pi-startup-summary-state { background: var(--al-success); }\n.pi-startup-disclosure.is-failed .pi-startup-summary-state { background: var(--al-danger); }\n.pi-startup-summary-copy { display: flex; min-width: 0; align-items: baseline; gap: 7px; overflow: hidden; white-space: nowrap; }\n.pi-startup-summary-copy b { flex: 0 0 auto; color: var(--al-ink); font-size: 12.5px; font-weight: 680; }\n.pi-startup-summary-copy small { min-width: 0; overflow: hidden; color: var(--al-muted); font-size: 11.5px; text-overflow: ellipsis; white-space: nowrap; }\n.pi-startup-summary-time { color: var(--al-muted); font: 11.5px/1 var(--font-mono); white-space: nowrap; }\n.pi-startup-chevron { color: var(--al-muted); font-size: 14px; text-align: center; transition: transform .15s ease; }\n.pi-startup-disclosure[open] .pi-startup-chevron { transform: rotate(180deg); }\n.pi-startup-body { padding: 0 10px 9px 27px; }\n.pi-startup-steps { display: grid; gap: 1px; border-top: 1px solid var(--al-line); padding-top: 6px; }\n.pi-startup-step {\n  display: grid;\n  min-height: 36px;\n  grid-template-columns: 18px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 7px;\n  padding: 3px 0;\n}\n.pi-startup-step-dot {\n  display: grid;\n  width: 15px;\n  height: 15px;\n  place-items: center;\n  border: 1px solid var(--al-line-strong);\n  border-radius: 50%;\n  color: transparent;\n  font-size: 9px;\n  font-weight: 800;\n}\n.pi-startup-step.is-done .pi-startup-step-dot { border-color: color-mix(in srgb, var(--al-success) 65%, var(--al-line)); background: var(--al-success); color: var(--al-on-accent); }\n.pi-startup-step.is-active .pi-startup-step-dot { border-color: var(--al-accent); background: color-mix(in srgb, var(--al-accent) 18%, transparent); box-shadow: inset 0 0 0 4px var(--al-surface); }\n.pi-startup-step.is-failed .pi-startup-step-dot { border-color: var(--al-danger); background: var(--al-danger); color: var(--al-on-accent); }\n.pi-startup-step-copy { display: grid; min-width: 0; gap: 1px; }\n.pi-startup-step-copy b { color: var(--al-ink-2); font-size: 12px; font-weight: 620; }\n.pi-startup-step-copy small { color: var(--al-muted); font-size: 11px; }\n.pi-startup-step.is-pending .pi-startup-step-copy,\n.pi-startup-step.is-pending .pi-startup-step-time { opacity: .48; }\n.pi-startup-step-time { color: var(--al-muted); font: 11px/1 var(--font-mono); white-space: nowrap; }\n.pi-startup-step.is-active .pi-startup-step-time { color: var(--al-accent); }\n.pi-startup-step.is-failed .pi-startup-step-time { color: var(--al-danger); }\n.pi-startup-meta { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }\n.pi-startup-meta span { padding: 2px 6px; border-radius: 999px; background: var(--al-soft); color: var(--al-muted); font-size: 10.5px; }\n.pi-startup-resources { display: grid; gap: 4px; max-height: 280px; margin-top: 8px; overflow: auto; border-top: 1px solid var(--al-line); padding-top: 7px; }\n.pi-startup-resource-row { display: grid; grid-template-columns: 78px minmax(0, 1fr); gap: 7px; align-items: start; font-size: 11.5px; line-height: 1.45; }\n.pi-startup-resource-row b { color: var(--al-muted); font: 600 10.5px/1.55 var(--font-mono); white-space: nowrap; }\n.pi-startup-resource-row span { color: var(--al-ink-2); overflow-wrap: anywhere; }\n.pi-startup-output { display: grid; gap: 4px; margin-top: 8px; border-top: 1px solid var(--al-line); padding-top: 7px; }\n.pi-startup-output > b, .pi-startup-diagnostics > b { color: var(--al-muted); font: 600 10.5px/1.4 var(--font-mono); }\n.pi-startup-output pre { max-height: 150px; margin: 0; overflow: auto; padding: 6px 8px; border-radius: 7px; background: color-mix(in srgb, var(--al-soft) 72%, transparent); color: var(--al-ink-2); font: 10.5px/1.45 var(--font-mono); white-space: pre-wrap; overflow-wrap: anywhere; }\n.pi-startup-diagnostics { display: grid; gap: 3px; margin-top: 7px; }\n.pi-startup-diagnostics span { color: var(--al-warning); font-size: 11px; line-height: 1.4; }\n.pi-startup-failure { display: grid; gap: 3px; margin-top: 8px; padding: 8px 10px; border-radius: 8px; background: var(--al-danger-soft); color: var(--al-danger); font-size: 12px; }\n.pi-startup-failure b { font-weight: 700; }\n.pi-startup-actions { display: flex; justify-content: flex-end; gap: 6px; margin-top: 7px; }\n.pi-startup-actions:empty { display: none; }\n.pi-startup-actions button { height: 28px; padding: 0 9px; border: 1px solid var(--al-line); border-radius: 7px; background: var(--al-surface); color: var(--al-muted); font-size: 12px; }\n.pi-startup-actions button.primary { border-color: color-mix(in srgb, var(--al-accent) 32%, var(--al-line)); color: var(--al-accent); }\n.pi-startup-actions button:disabled { opacity: .5; }\n\n@media (max-width: 767.98px) {\n  .pi-startup-body { padding-left: 10px; }\n  .pi-startup-summary-copy small { display: none; }\n  .pi-startup-step-copy small { display: none; }\n  .pi-startup-resource-row { grid-template-columns: 1fr; gap: 1px; }\n}\n""",
)

write(
    "packages/web/src/features/pi-startup-observability.test.ts",
    """import assert from 'node:assert/strict'\nimport { readFileSync } from 'node:fs'\nimport test from 'node:test'\n\nconst page = readFileSync(new URL('./PiLivePage.tsx', import.meta.url), 'utf8')\nconst disclosure = readFileSync(new URL('../components/PiStartupDisclosure.tsx', import.meta.url), 'utf8')\nconst css = readFileSync(new URL('../components/pi-startup-disclosure.css', import.meta.url), 'utf8')\n\ntest('Pi Live exposes real Runtime initialization stages, timings and failure location', () => {\n  assert.match(page, /<PiStartupDisclosure/)\n  assert.match(page, /event\\.timings \\?\\? event\\.initializationTimings/)\n  assert.match(page, /initializationElapsedMs/)\n  assert.match(disclosure, /state\\.initializationTimings/)\n  assert.match(disclosure, /启动 Runtime Worker/)\n  assert.match(disclosure, /加载 Pi SDK/)\n  assert.match(disclosure, /加载资源/)\n  assert.match(disclosure, /创建 Pi Session/)\n  assert.match(disclosure, /绑定扩展界面/)\n  assert.match(disclosure, /卡在：/)\n})\n\ntest('Pi startup detail mirrors actual loaded resource groups and extension startup output', () => {\n  assert.match(page, /type === 'runtime_resources'/)\n  assert.match(page, /type === 'runtime_output'/)\n  assert.match(page, /startupResources/)\n  assert.match(page, /startupOutput/)\n  assert.match(disclosure, /label: 'Context'/)\n  assert.match(disclosure, /label: 'Skills'/)\n  assert.match(disclosure, /label: 'Prompts'/)\n  assert.match(disclosure, /label: 'Extensions'/)\n  assert.match(disclosure, /label: 'Themes'/)\n  assert.match(disclosure, /\\[启动输出\\]/)\n  assert.match(disclosure, /Pi v\\{sdkVersion\\}/)\n})\n\ntest('Pi initialization disclosure collapses after ready and expands on failure', () => {\n  assert.match(disclosure, /state\\.status === 'ready'\\) setExpanded\\(false\\)/)\n  assert.match(disclosure, /state\\.status === 'failed'\\) setExpanded\\(true\\)/)\n  assert.match(disclosure, /onToggle=\\{event => setExpanded\\(event\\.currentTarget\\.open\\)\\}/)\n})\n\ntest('ready startup summary stays on one compact line', () => {\n  assert.match(disclosure, /state\\.status !== 'ready' && <small>/)\n  assert.match(css, /\\.pi-startup-summary-copy \\{[^}]*display:\\s*flex;/)\n  assert.match(css, /\\.pi-startup-disclosure\\.is-ready:not\\(\\[open\\]\\) > summary \\{[^}]*min-height:\\s*34px;/)\n})\n""",
)

